462	\begin{lemma}[Restricted line distributions and error inflation]
463		\label{lem:restricted-line-mixture-bounds}
464		% This node corresponds to unlabelled prose in the source (the discussion
465		% following def:ith-restricted-line, lines 1049-1061 of the paper file).
466		\uses{def:ith-restricted-line, def:line-point-dist, lem:qld-xz-lines,
467			lem:qld-4-10, def:expanded-state}
468		The distribution $D_{\mathrm{ALine}}$ is a uniform mixture of the
469		distributions $D_{\mathrm{ALine},i}$ for $i \in \{1, \dots, m\}$, and
470		likewise $D_{\mathrm{DLine}}$ is a uniform mixture of the
471		$D_{\mathrm{DLine},i}$. As a consequence:
472		\begin{enumerate}
473			\item any approximation that holds on average over the line-point
474			distribution $D_{\mathrm{Line}}$ with error $\delta$ holds over each
475			restricted distribution $D_{\mathrm{ALine},i}$ and
476			$D_{\mathrm{DLine},i}$ with error $2m\delta$;
477			\item any approximation that holds on average over
478			$D_{\mathrm{Line}} \times D_{\mathrm{Line}}$ holds over any product
479			of restricted distributions with error $4m^2\delta$;
480			\item in particular, by Lemma~\ref{lem:qld-xz-lines}, for any types
481			$\mathrm{v}_1, \mathrm{v}_2 \in \{\mathrm{ALine},
482			\mathrm{DLine}\}$ and any $i, j \in \{1, \dots, m\}$,
483			\begin{equation}
484				\label{eq:qld-xz-lines-restricted}
485				\E_{(\ell_X,x) \sim D_{\mathrm{v}_1,i}}\
486				\E_{(\ell_Z,z) \sim D_{\mathrm{v}_2,j}}
487				\sum_{f_X,f_Z}
488				\bra{\hat\psi}
489				\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'}
490				\ot
491				\big(\Id - \hat{Q}^{x,z}_{f_X(x),f_Z(z)}
492				\big)_{\mathsf{B}\mathsf{A}''}
493				\ket{\hat\psi}
494				= O(m^2 \delta_P)\,.
495			\end{equation}
496		\end{enumerate}
497	\end{lemma}
498	\begin{proof}
499		\uses{lem:qld-xz-lines, def:line-point-dist, def:consistency}
500		The line-point distribution places weight $\tfrac{1}{2}$ on each of the
501		axis-parallel and diagonal components and, within each component, uniform
502		weight on the index $i$, so each restricted distribution carries mixture
503		weight $\tfrac{1}{2m}$ in $D_{\mathrm{Line}}$. A nonnegative average that
504		is at most $\delta$ therefore bounds each mixture component by
505		$2m\delta$, and products of two such mixtures give the factor
506		$(2m)^2 = 4m^2$. The instance \eqref{eq:qld-xz-lines-restricted} is item
507		2 applied to the conclusion of Lemma~\ref{lem:qld-xz-lines}, whose
508		$\simeq_{\delta_P}$ relation over two independent copies of the
509		line-point distribution is precisely the statement that the left-hand
510		side of \eqref{eq:qld-xz-lines-restricted}, averaged over
511		$D_{\mathrm{Line}} \times D_{\mathrm{Line}}$, is at most $\delta_P$.
512	\end{proof}
