 95	The soundness properties of the low individual degree game are expressed in terms of the following class of measurements.
 96	
 97	\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
 98		\uses{def:polyfunc, def:polymeasurements}
 99		Let $\polymeas{m}{q}{d}$ denote the set of POVM measurements whose outcomes correspond to polynomials $g\colon \F_q^m \to \F_q$ of individual degree at most $d$, that is, measurements indexed by $\polyfunc{m}{q}{d}$; this is the notion of Definition~\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). More generally, for an integer $k$ and tuples $m = (m_1,\ldots,m_k)$, $q = (q_1,\ldots,q_k)$, $d = (d_1,\ldots,d_k)$, let $\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \{G_{g_1,\ldots,g_k}\}$ such that for each $i \in \{1,\ldots,k\}$, the outcome index $g_i$ is a polynomial $g_i\colon \F_{q_i}^{m_i} \to \F_{q_i}$ of individual degree at most $d_i$.
100	\end{definition}
375	\section{Canonical parameters of the Pauli basis test}
376	% Paper label sec:qld-complexity kept for cross-reference fidelity (the complexity
377	% statements of that subsection are outside the scope of this development).
378	\label{sec:qld-complexity}
379	
380	We specify a canonical setting of the parameter tuple $\mathsf{qldparams}$ as a function of an integer $R$, and bound the resulting soundness function. All logarithms are base $2$.
381	
382	\begin{definition}[Canonical parameters of the Pauli basis test]\label{def:introparams}
383		\uses{thm:pauli}
384		Let $a, b$ be the universal constants of Theorem~\ref{thm:pauli}, and let $c$ be the smallest \emph{even} integer that is at least $(b+a)/b$. For every integer $R \ge 4$, define the tuple $\mathsf{introparams}(R) = (q, m, d)$ by
385		\begin{itemize}
386			\item $q = 2^k$ for $k = c \lceil \log \log R \rceil + 1$,
387			\item $m = 2^j$, where $j$ is the unique integer with $2^j \le c \lceil \log R \rceil + 1 < 2^{j+1}$,
388			\item $d = 1$.
389		\end{itemize}
390		The letter $k$ here denotes the exponent of the field size and is unrelated to the simultaneity parameter $k$ of the classical game. With this choice the Pauli basis test certifies the presence of an $M = 2^m$-qudit maximally entangled state of local dimension $q$, equivalently an $(M \log q)$-qubit EPR state, and the choice $d = 1$ runs the low individual degree test multilinearly.
391	\end{definition}
392	
393	\begin{lemma}[Soundness bound for the canonical parameters]\label{lem:delta-bound}
394		\uses{def:introparams, def:admissible, thm:pauli}
395		For all integers $R \ge 4$, the parameter tuple $\mathsf{introparams}(R) = (q,m,d)$ is admissible (Definition~\ref{def:admissible}) and satisfies $2^m \ge R$. Furthermore, there exist universal constants $a' \ge 1$ and $0 < b' \le 1$ such that the function $\delta_{\mathrm{qld}}(\eps, m, d, q)$ of Theorem~\ref{thm:pauli} is at most
396		\[
397			a' \bigl( (\log R)^{a'} \cdot \eps^{b'} + (\log R)^{-b'} \bigr)\;.
398		\]
399	\end{lemma}
400	\begin{proof}
401		\uses{def:introparams, def:admissible, def:admissible-size, thm:pauli}
402		Since $c$ is even, the exponent $k = c \lceil \log\log R \rceil + 1$ is odd, so $q = 2^k$ is an admissible field size; and $m$ divides $q$ because $2^j \le c \lceil \log R \rceil + 1 \le 2 \log^c R \le 2^k$, so $j \le k$ and both are powers of $2$. Since $m = 2^j \ge (c/2) \log R$, we get $2^m \ge R^{c/2} \ge R$, using $c \ge 2$. For the soundness bound, first observe that $k \le m$ gives $2^{-bmd} \le q^{-b}$, so $\delta_{\mathrm{qld}}(\eps,m,d,q) \le a (md)^a (\eps^b + 2 q^{-b})$. Using $d = 1$, $m \le 2c \log R$, and $q \ge \log^c R$, this is at most $2a(2c)^a \bigl( (\log R)^a \eps^b + (\log R)^{a - cb} \bigr)$; and since $cb - a \ge b \ge 0$ by the choice of $c$, the second exponent is at most $-b$. The statement follows with $a' = 2a(2c)^a$ and $b' = b$.
403	\end{proof}
405	\section{Lines}
406	
407	The question distributions of the classical low individual degree game and of
408	the Pauli basis test (Chapter~\ref{chap:qpbt-test}) sample lines in $\F_q^m$;
409	we record here the definition of lines and their canonical representatives.
410	
411	\begin{definition}[Lines]\label{def:line}
412		A \emph{line} $\ell$ in $\F_q^m$ specified by a pair
413		$(u,v) \in (\F_q^m)^2$ is the subset
414		\begin{equation}\label{eq:line-set}
415			\ell(u,v) = \bigl\{\, u + tv : t \in \F_q \,\bigr\} \subseteq \F_q^m\;.
416		\end{equation}
417		The vector $v$ is called a \emph{direction} of $\ell(u,v)$; the case $v = 0$
418		is explicitly allowed, in which case the line is the singleton $\{u\}$. A
419		line $\ell(u,v)$ is \emph{axis-parallel} if there is a coordinate
420		$i \in \{1, \dots, m\}$ for which $v = e_i$, the $i$-th elementary basis
421		vector of $\F_q^m$; such a line is said to be \emph{parallel to the $i$-th
422		direction}. A line $\ell(u,v)$ is \emph{diagonal} if there exists
423		$i \in \{0, 1, \dots, m-1\}$ such that $v_1 = v_2 = \dots = v_i = 0$ (for
424		$i = 0$ the condition is vacuous, so every line is diagonal).
425	\end{definition}
426	
427	\begin{proposition}\label{prop:line-equiv}
428		\uses{def:line}
429		Let $u, v \in \F_q^m$. Then for all $u' \in \ell(u,v)$, we have
430		$\ell(u,v) = \ell(u',v)$.
431	\end{proposition}
432	\begin{proof}
433		\uses{def:line}
434		Fix $u' \in \ell(u,v)$, so $u' = u + tv$ for some $t \in \F_q$. Any
435		$a \in \ell(u,v)$ has the form $a = u + sv = u' + (s - t)v$, so
436		$\ell(u,v) \subseteq \ell(u',v)$. The symmetric argument gives the reverse
437		inclusion.
438	\end{proof}
439	
440	Thus, for a fixed direction, a line is an equivalence class of its points: the
441	pair $(u,v)$ representing it can use any base point on the line. A canonical
442	representation is obtained as follows.
443	
444	\begin{definition}[Canonical representative of a line]\label{def:line-representative}
445		\uses{def:line, def:cl-canonical, prop:line-equiv}
446		Let $\ell$ be a line in direction $v \neq 0$, and let
447		$L^{\mathrm{Ln}}_v : \F_q^m \to \F_q^m$ denote the canonical linear map with
448		the one-dimensional kernel basis $\{v\}$
449		(Definition~\ref{def:cl-canonical}). The \emph{canonical representative of
450		$\ell$} is the point $u_0 \in \F_q^m$ such that
451		\[
452			u_0 = L^{\mathrm{Ln}}_v(u) \qquad \text{for all } u \in \ell\;.
453		\]
454		This is well defined: since the image and kernel of $L^{\mathrm{Ln}}_v$ are
455		complementary, any $u \in \ell$ decomposes uniquely as $u = u_0 + tv$ with
456		$u_0$ in the image, so $u_0 = u - tv \in \ell$ and
457		$L^{\mathrm{Ln}}_v(u_0) = u_0$; moreover any two points of $\ell$ differ by
458		a multiple of $v$ and therefore have the same image under
459		$L^{\mathrm{Ln}}_v$. A line $\ell = \ell(u,v)$ is henceforth canonically
460		represented by the pair $(u_0, v)$. (For $v = 0$, where the singleton
461		$\{u\}$ leaves no independent kernel basis, we take $L^{\mathrm{Ln}}_0$ to
462		be the identity---the canonical linear map with empty kernel basis---so
463		that $u_0 = u$; the source leaves this case implicit.)
464	\end{definition}
465	
466	\section{Quantum registers and EPR states}
467	% Paper label sec:lin-reg kept for cross-reference fidelity.
468	\label{sec:lin-reg}
469	
470	\begin{definition}[State space of a linear register]\label{def:lin-reg}
471		\uses{def:complementary}
472		For a set $V$, we write $\C^V$ for the complex vector space of dimension
473		$|V|$, endowed with the canonical orthonormal basis
474		$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
475		$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
476		subspaces over $\F$, then $\C^V$ is identified with
477		$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
478		$\ket{x_1 \oplus \dots \oplus x_k}$ with
479		$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
480		$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
481		$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
482		the \emph{qudits} of $\C^V$.
483	\end{definition}
484	
485	\begin{definition}[EPR state]\label{def:EPR}
486		\uses{def:lin-reg}
487		For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
488		$\C^V \ot \C^V$ is
489		\[
490			\ket{\mathrm{EPR}}_V
491			= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
492		\]
493		We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
494		$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
495	\end{definition}
