 42	\section{Games and strategies}
 43	% Paper subsection label sec:strat kept for cross-reference fidelity.
 44	\label{sec:strat}
 45	
 46	\begin{definition}[Two-player one-round games]\label{def:game}
 47		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
 48		\begin{enumerate}
 49			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
 50			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
 51			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
 52			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
 53		\end{enumerate}
 54	\end{definition}
 55	
 56	\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
 57		\uses{def:game, def:povm-conventions}
 58		A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
 59		\begin{itemize}
 60			\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
 61			\item $A$ is a set $\{A^x\}$ such that for every $x \in \mathcal X$, $A^x = \{A^x_a\}_{a \in \mathcal A}$ is a POVM on $\mathcal H_A$, and
 62			\item $B$ is a set $\{B^y\}$ such that for every $y \in \mathcal Y$, $B^y = \{B^y_b\}_{b \in \mathcal B}$ is a POVM on $\mathcal H_B$.
 63		\end{itemize}
 64	\end{definition}
 65	
 66	\begin{definition}[Tensor product value]\label{def:tensor-product-value}
 67		\uses{def:tensor-product-strategy}
 68		The \emph{tensor product value} of a tensor product strategy $\mathcal S = (\ket{\psi}, A, B)$ with respect to a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is
 69		\[
 70			\operatorname{val}^*(\mathfrak G, \mathcal S) = \sum_{x,\,y,\,a,\,b} \mu(x,y)\, D(x,y,a,b)\, \bra{\psi} A^x_a \ot B^y_b \ket{\psi}\,.
 71		\]
 72		For $v \in [0,1]$ we say that the strategy $\mathcal S$ \emph{passes (or wins) $\mathfrak G$ with probability $v$} if $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge v$. The \emph{tensor product value} of $\mathfrak G$ is
 73		\[
 74			\operatorname{val}^*(\mathfrak G) = \sup_{\mathcal S} \operatorname{val}^*(\mathfrak G, \mathcal S)\,,
 75		\]
 76		where the supremum is taken over all tensor product strategies $\mathcal S$ for $\mathfrak G$.
 77	\end{definition}
 78	
 79	Unless specified otherwise, all strategies considered in what follows are tensor product strategies, and we simply call them \emph{strategies}; similarly, we refer to $\operatorname{val}^*(\mathfrak G)$ as the \emph{value} of the game $\mathfrak G$.
 80	
200			\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
201		\end{enumerate}
202	\end{definition}
203	
204	\begin{remark}[Asymptotic reading of the distance relations]\label{rem:asymptotic-distance}
205		Definitions~\ref{def:state-distance}, \ref{def:consistency}, and \ref{def:povm-distance} are asymptotic: every $\approx_\delta$ and $\simeq_\delta$ statement refers to families of states and measurement families indexed by an implicit parameter $n \in \N$, and the $O(\cdot)$ is taken as $n \to \infty$. None of these relations is a pointwise inequality with an explicit constant. By contrast, the corresponding relations used in the low individual degree chapters (Definitions~\ref{def:simeq} and~\ref{def:approx_delta}) carry no hidden constant. A formalization of the present chapter must therefore fix concrete-constant versions of the relations and re-verify the constant in each conversion fact below; for instance, the triangle inequality of Lemma~\ref{fact:triangle} hides a factor $2$ in the $O(\cdot)$.
206	\end{remark}
207	
208	We record several useful facts about the consistency measure and the state-dependent distance. For the statements imported without proof, readers are referred to Sections~4.4 and~4.5 of \cite{Natarajan2018NEEXP}.
209	
210	\begin{lemma}[Consistency versus closeness; Facts 4.13 and 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
211		\uses{def:consistency, def:povm-distance}
212		For POVMs $\{A^x_a\}$ and $\{B^x_a\}$, the following hold.
213		\begin{enumerate}
214			\item If $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$.
215			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ \emph{and} $\{A^x_a\}$ and $\{B^x_a\}$ are projective measurements, then $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$.
216			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
217		\end{enumerate}
218	\end{lemma}
219	\begin{proof}
220		Stated in the source without proof; these are Facts 4.13 and 4.14 of \cite{Natarajan2018NEEXP}. For the first item, expand each term $\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \rVert^2$ and use $ (A^x_a)^2 \le A^x_a$, $(B^x_a)^2 \le B^x_a$ together with completeness of the two POVMs: summing over $a$ and averaging over $x$ leaves exactly twice the off-diagonal mass, which is $O(\delta)$ by hypothesis. For the converse items, write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$ and use projectivity of both families, or of one family combined with the Cauchy--Schwarz inequality; the latter route costs a square root in the error.
221	\end{proof}
222	
223	\begin{lemma}[Fact 4.20 in \cite{Natarajan2018NEEXP}]\label{fact:add-a-proj}
224		\uses{def:povm-distance}
225		Let $\mathcal A, \mathcal B, \mathcal C$ be finite sets, and let $\mu$ be a distribution over question pairs $(x,y)$. Let $\{A^x_{a,\,b}\}$ and $\{B^x_{a,\,b}\}$ be operators whose outcomes range over the product set $\mathcal A \times \mathcal B$. Suppose a set of operators $\{C^y_{a,\,c}\}$, whose outcomes range over the product set $\mathcal A \times \mathcal C$, satisfies the condition $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$ for all $a$ and all $y$. If $A^x_{a,\,b} \approx_\delta B^x_{a,\,b}$ on average over $x$ sampled from the corresponding marginal of the distribution $\mu$, then $C^y_{a,\,c} A^x_{a,\,b} \approx_\delta C^y_{a,\,c} B^x_{a,\,b}$ on average over $(x,y)$ sampled from $\mu$.
226	\end{lemma}
227	\begin{proof}
228		Fix questions $x, y$ and answers $a \in \mathcal A$, $b \in \mathcal B$. Then
229		\begin{align*}
230			\sum_c \bigl\lVert (C^y_{a,\,c} A^x_{a,\,b} - C^y_{a,\,c} B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2
231			&= \bra{\psi} (A^x_{a,\,b} - B^x_{a,\,b})^\dagger \Bigl( \sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \Bigr) (A^x_{a,\,b} - B^x_{a,\,b}) \ket{\psi}\\
232			&\le \bigl\lVert (A^x_{a,\,b} - B^x_{a,\,b})\, \ket{\psi} \bigr\rVert^2\,,
233		\end{align*}
234		where the inequality uses the assumption $\sum_c (C^y_{a,\,c})^\dagger C^y_{a,\,c} \le \Id$. Summing over $a, b$ and averaging over $(x,y) \sim \mu$ yields the conclusion.
235	\end{proof}
236	
237	\begin{lemma}[Multiplying by function-indexed operators]\label{fact:add-a-proj2}
238		\uses{def:povm-distance}
239		Let $\mathcal X, \mathcal A$ be finite sets, and let $\mathcal G$ be a set of functions $g \colon \mathcal X \to \mathcal A$. Let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs indexed by $\mathcal X$ with outcomes in $\mathcal A$. Let $\{S^x_g\}_{x \in \mathcal X,\, g \in \mathcal G}$ be a set of operators such that for all $x \in \mathcal X$, $\sum_g (S^x_g)^\dagger S^x_g \le \Id$. If $A^x_a \approx_\delta B^x_a$ on average over $x$, then $S^x_g A^x_{g(x)} \approx_\delta S^x_g B^x_{g(x)}$.
240	\end{lemma}
241	\begin{proof}
242		Expand the left-hand side and group the sum over $g$ according to the value $a = g(x)$:
243		\[
244			\E_x \sum_g \bigl\lVert S^x_g (A^x_{g(x)} - B^x_{g(x)})\, \ket{\psi} \bigr\rVert^2
245			= \E_x \sum_a \bra{\psi} (A^x_a - B^x_a)^\dagger \Bigl( \sum_{g\,:\,g(x)=a} (S^x_g)^\dagger S^x_g \Bigr) (A^x_a - B^x_a) \ket{\psi}\,.
246		\]
247		Since $\sum_{g\,:\,g(x)=a} (S^x_g)^\dagger S^x_g \le \sum_g (S^x_g)^\dagger S^x_g \le \Id$, this is at most $\E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2 \le \delta$.
248	\end{proof}
249	
250	\begin{lemma}[Absorbing an approximating family into a projective sum]\label{lem:cool-closeness-fact}
251		\uses{def:povm-distance, def:povm-conventions}
252		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\{A^x_a\}_{a \in \mathcal A}$ be a projective measurement and let $\{B^x_a\}_{a \in \mathcal A}$ be a set of matrices. If $A^x_a \approx_\delta B^x_a$, then for all subsets $S \subseteq \mathcal A$ we have
253		\[
254			\sum_{a \in S} A^x_a \approx_\delta \sum_{a \in S} A^x_a \cdot B^x_a\,.
255		\]
256	\end{lemma}
257	\begin{proof}
258		By projectivity, $\sum_{a \in S} (A^x_a - A^x_a B^x_a) = \sum_{a \in S} A^x_a (A^x_a - B^x_a)$. Expanding the squared norm of the corresponding vector, the cross terms for distinct $a \ne a' \in S$ vanish because $A^x_a A^x_{a'} = 0$, so
259		\begin{align*}
260			\E_x \Bigl\lVert \sum_{a \in S} \bigl(A^x_a - A^x_a B^x_a\bigr) \ket{\psi} \Bigr\rVert^2
261			&= \E_x \sum_{a \in S} \bra{\psi} (A^x_a - B^x_a)^\dagger A^x_a (A^x_a - B^x_a) \ket{\psi}\\
262			&\le \E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2\,,
263		\end{align*}
264		where the last step uses $A^x_a \le \Id$. All expectations are taken according to $\mu$, and the last quantity is at most $\delta$ by assumption.
265	\end{proof}
266	
267	\begin{lemma}[Triangle inequality; Fact 4.28 in \cite{Natarajan2018NEEXP}]\label{fact:triangle}
268		\uses{def:povm-distance}
269		If $A^x_a \approx_\delta B^x_a$ and $B^x_a \approx_{\eps} C^x_a$, then $A^x_a \approx_{\delta+\eps} C^x_a$.
270	\end{lemma}
271	\begin{proof}
272		Stated in the source without proof; it is Fact 4.28 of \cite{Natarajan2018NEEXP}. For every $x$ and $a$, $\lVert (A^x_a - C^x_a)\ket{\psi} \rVert^2 \le 2\lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2 + 2\lVert (B^x_a - C^x_a)\ket{\psi} \rVert^2$. Averaging over $x$ and summing over $a$ gives the claim; the factor $2$ is absorbed by the $O(\cdot)$ in Definition~\ref{def:povm-distance}.
273	\end{proof}
274	
275	\begin{lemma}[Triangle inequality for ``$\simeq$''; Proposition 4.29 in \cite{Ji2020LowIndividualDegree}]\label{fact:triangle-for-simeq}
276		\uses{def:consistency}
277		If $A^x_a \ot \Id_B \simeq_{\eps} \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, and $C^x_a \ot \Id_B \simeq_\gamma \Id_A \ot D^x_a$, then
278		\[
279			A^x_a \ot \Id_B \simeq_{\eps + 2\sqrt{\delta+\gamma}} \Id_A \ot D^x_a\,.
280		\]
281	\end{lemma}
282	\begin{proof}
283		\uses{fact:agreement}
284		Stated in the source without proof; it is Proposition 4.29 of \cite{Ji2020LowIndividualDegree}. The two hypotheses involving $C$ convert, via Lemma~\ref{fact:agreement}, into state-dependent closeness of $C^x_a \ot \Id_B$ to both $\Id_A \ot B^x_a$ and $\Id_A \ot D^x_a$, hence of $\Id_A \ot B^x_a$ to $\Id_A \ot D^x_a$ at cost $O(\delta+\gamma)$. The first consistency then transfers from $B$ to $D$ by expanding the off-diagonal mass and applying the Cauchy--Schwarz inequality, which turns the squared-distance bound into the term $2\sqrt{\delta+\gamma}$.
285	\end{proof}
286	
287	\begin{lemma}[Data processing; Fact 4.26 in \cite{Natarajan2018NEEXP}]\label{fact:data-processing}
288		\uses{def:consistency, def:bracket}
289		Suppose $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$. Then for any function $f$ on the outcome set,
290		\[
291			A^x_{[f(\cdot)=b]} \ot \Id_B \simeq_\delta \Id_A \ot B^x_{[f(\cdot)=b]}\,.
292		\]
293	\end{lemma}
294	\begin{proof}
295		Stated in the source without proof; it is Fact 4.26 of \cite{Natarajan2018NEEXP}. Every off-diagonal pair $(b, b')$ with $b \ne b'$ of the post-processed families pulls back to pairs $(a, a')$ with $f(a) = b \ne b' = f(a')$, and in particular $a \ne a'$. Coarse-graining therefore only merges terms of the off-diagonal sum, so the post-processed off-diagonal mass is at most the original one.
296	\end{proof}
