333	\begin{lemma}[Sandwiched simultaneous measurement; modified from Fact 4.34 in \cite{Natarajan2018NEEXP}]\label{lem:ld-sandwich}
358	\begin{lemma}[Pasting two consistent measurements; Fact 4.35 in \cite{Natarajan2018NEEXP}]\label{lem:pasting}
359		\uses{def:consistency, def:bracket, def:povm-conventions}
360		Let $\mathcal D$ be a distribution on $(x, y_1, y_2) \in \mathcal X \times \mathcal Y_1 \times \mathcal Y_2$. For $i \in \{1,2\}$ let $\mathcal G_i$ be a collection of functions $g_i \colon \mathcal Y_i \to \mathcal R_i$ and let $\{(G_i)^x_g\}_{g \in \mathcal G_i}$ be families of measurements such that $\{(G_2)^x_g\}_g$ is projective for every $x$. Suppose further that for every $(x, y_1)$ it holds that for $g_2 \ne g_2' \in \mathcal G_2$ the probability, on average over $y_2$ chosen from $\mathcal D$ conditioned on $(x, y_1)$, that $g_2(y_2) = g_2'(y_2)$ is at most $\eta$. Let $\{A^{x,y_1,y_2}_{a_1,\,a_2}\}$ be a family of projective measurements with outcomes $(a_1, a_2) \in \mathcal R_1 \times \mathcal R_2$ such that for $i \in \{1,2\}$,
361		\begin{equation}\label{eq:pasting-1}
362			A^{x,y_1,y_2}_{a_i} \ot \Id \simeq_\delta \Id \ot (G_i)^x_{[\operatorname{eval}_{y_i}(\cdot)=a_i]}
363		\end{equation}
364		and
365		\begin{equation}\label{eq:pasting-2}
366			A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_\delta \Id \ot A^{x,y_1,y_2}_{a_1,\,a_2}\,,
367		\end{equation}
368		where $A^{x,y_1,y_2}_{a_i}$ denotes the marginal on the $i$-th part of the outcome (Definition~\ref{def:povm-conventions}). Define a family of measurements $\{J^x_{g_1,\,g_2}\}$ by
369		\begin{equation}\label{eq:pasting-2a}
370			J^x_{g_1,\,g_2} = (G_2)^x_{g_2}\, (G_1)^x_{g_1}\, (G_2)^x_{g_2}\,.
371		\end{equation}
372		Then there is a
373		\begin{equation}\label{eq:def-deltap}
374			\delta_{\mathrm{pasting}} = \delta_{\mathrm{pasting}}(\eta, \delta) = \poly(\eta, \delta)
375		\end{equation}
376		such that
377		\begin{equation}\label{eq:pasting-3}
378			A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_{\delta_{\mathrm{pasting}}} \Id \ot J^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1,\, \operatorname{eval}_{y_2}(\cdot)=a_2]}\,.
379		\end{equation}
380		Neither the exponent nor the constant in $\poly(\eta, \delta)$ is made explicit in the source; both are universal constants inherited from the proof of Fact 4.35 in \cite{Natarajan2018NEEXP}.
381	\end{lemma}
382	\begin{proof}
383		Stated in the source without proof, as an import of Fact 4.35 of \cite{Natarajan2018NEEXP}. The measurement $J^x$ sandwiches the family $(G_1)^x$ between two copies of the projective family $(G_2)^x$. The consistency hypotheses \eqref{eq:pasting-1} and the self-consistency \eqref{eq:pasting-2} allow the joint measurement $A^{x,y_1,y_2}$ to be compared with the sandwiched product one factor at a time, and the $\eta$-bound on the pairwise agreement of distinct functions in $\mathcal G_2$ controls the error terms arising when two different outcomes $g_2 \ne g_2'$ agree at the sampled point $y_2$.
384	\end{proof}
