397	\section{Conditionally linear functions and distributions}
398	% Paper subsection label sec:cl kept for cross-reference fidelity.
399	\label{sec:cl}
400	
401	Conditionally linear functions specify the question distributions of the games considered in the following chapters in a form that can be ``introspected''. Intuitively, a conditionally linear function takes as input an element $x \in V = \F^n$ and applies linear maps $L_j$ sequentially to $x^{V_j}$, where $V_1, V_2, \dots$ is a sequence of complementary register subspaces such that both the linear map $L_j$ and the subspace $V_j$, for $j \ge 2$, may depend on the values taken by the previous linear maps $L_1(x^{V_1})$, $L_2(x^{V_2})$, and so on.
402	
403	Throughout this section $V$ denotes the linear space $\F^n$ for some integer $n \ge 0$, and all the distinguished subspaces of $V$ are register subspaces (Definition~\ref{def:register-subspace}). If $V_1, V_2, \dots, V_\ell$ are fixed subspaces of $V$ and $k \in \{1, 2, \dots, \ell\}$, we use the subscript range notation
404	\[
405		V_{<k} = \bigoplus_{j\,:\,1 \le j < k} V_j\,, \qquad V_{>k} = \bigoplus_{j\,:\,\ell \ge j > k} V_j\,,
406	\]
407	and $V_{\le k}$, $V_{\ge k}$ are understood to be $V_{<k+1}$ and $V_{>k-1}$, respectively. For a register subspace $V'$ of $V$, the symbol $x^{V'}$ denotes the projection of $x$ onto $V'$ parallel to the complementary register subspace (Definition~\ref{def:complementary}). Moreover, if $F \colon V' \to V'$ is a function and $x \in V$, we write $x^F$ for $F(x^{V'})$; for example, in the following definition $x^{L_1}$ is shorthand for $L_1(x^{V_1})$.
408	
409	\begin{definition}[Conditionally linear functions]\label{def:cl-func}
410		\uses{def:register-subspace, def:complementary}
411		Let $V$ be $\F^n$ for some $n \ge 0$. For all integers $\ell \ge 0$ the collection of \emph{$\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is defined inductively as follows.
412		\begin{enumerate}
413			\item There is a single $0$-level conditionally linear function, which is the $0$ function on $V$.
414			\item Let $\ell \ge 1$ and suppose the collection of $(\ell-1)$-level conditionally linear functions has been defined. The collection of $\ell$-level conditionally linear functions on $V$ consists of all functions $L$ on $V$ that can be expressed in the following form: there exist complementary register subspaces $V_1$ and $V_{>1}$ of $V$, a linear function $L_1$ on $V_1$, and, for all $v \in L_1(V_1)$, an $(\ell-1)$-level conditionally linear function $L_{>1,\,v}$ on $V_{>1}$, such that for all $x \in V$,
415			\[
416				L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})\,.
417			\]
418		\end{enumerate}
419	\end{definition}
420	
421	We abbreviate ``conditionally linear'' as \emph{CL}. Operationally, an $\ell$-level CL function first applies $L_1$ to $x^{V_1}$; conditioned on the value $x^{L_1}$ it selects a register subspace $V_2$ and a linear map $L_2$ and applies $L_2$ to $x^{V_2}$; and so on, finally outputting $\sum_{k=1}^{\ell} x^{L_k}$. Every $1$-level CL function is linear, and conversely every linear map on $V$ is a $1$-level CL function. Moreover, for every $\ell \ge 1$ the collection of $\ell$-level CL functions contains the collection of $(\ell-1)$-level CL functions.
422	
423	\begin{definition}[Conditionally linear distributions]\label{def:cl-dist}
424		\uses{def:cl-func}
425		Let $L, R \colon V \to V$ be conditionally linear functions. The \emph{conditionally linear distribution $\mu_{L,R}$ corresponding to $(L,R)$} is the distribution over pairs $(L(x), R(x)) \in V \times V$ for $x$ drawn uniformly at random from $V$.
426	\end{definition}
427	
428	Note that both players' questions are generated from the \emph{same} uniformly random seed $x$; this shared-seed structure is what the introspection technique exploits. The following lemma elucidates the structural properties of $\ell$-level CL functions. Recall that $x^{L_{<k}}$ and $x^{L_k}$ denote $L_{<k}(x)$ and $L_{k,\,u}(x^{V_{k,\,u}})$ where $u = L_{<k}(x)$.
429	
430	\begin{lemma}[Structure of conditionally linear functions]\label{lem:cl-kth}
431		\uses{def:cl-func, def:register-subspace}
432		Let $\ell \ge 1$ and $V = \F^n$ for some integer $n \ge 0$. A function $L \colon V \to V$ is an $\ell$-level CL function if and only if the following collection of functions and subspaces exists:
433		\begin{enumerate}
434			\item[(i)] for each $k \in \{1, 2, \dots, \ell\}$, a function $L_{\le k} \colon V \to V$, called the \emph{$k$-th marginal of $L$};
435			\item[(ii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a register subspace $V_{k,\,u}$ of $V$, called the \emph{$k$-th factor space with prefix $u$};
436			\item[(iii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a linear map $L_{k,\,u} \colon V_{k,\,u} \to V_{k,\,u}$, called the \emph{$k$-th linear map of $L$ with prefix $u$};
437		\end{enumerate}
438		such that the following conditions hold for all $k \in \{1, 2, \dots, \ell\}$:
439		\begin{enumerate}
440			\item $L_{\le k}$ is a $k$-level CL function on $V$;
441			\item $V = \bigoplus_{i=1}^{\ell} V_{i,\,x^{L_{<i}}}$ for all $x \in V$;
442			\item $L_{\le k}(x) = \sum_{i=1}^{k} x^{L_i}$ for all $x \in V$, where $L_i$ is shorthand notation for $L_{i,\,x^{L_{<i}}}$;
443			\item $L = L_{\le \ell}$.
444		\end{enumerate}
445		As in condition 3, we sometimes use $V_k$ and $L_k$ to denote $V_{k,\,u}$ and $L_{k,\,u}$ respectively, leaving the prefix $u$ implicit.
446	\end{lemma}
447	\begin{proof}
448		For the ``if'' direction, conditions 1 and 4 immediately exhibit $L$ as an $\ell$-level CL function. For the ``only if'' direction one constructs the marginals, factor spaces, and linear maps by induction on $\ell$. In the base case $\ell = 1$ take $L_{\le 1} = L$, $V_1 = V$, and $L_1 = L$. For the inductive step, write $L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})$ as in Definition~\ref{def:cl-func} and apply the inductive hypothesis to each $(\ell-1)$-level function $L_{>1,\,v}$, obtaining its marginals, factor spaces, and linear maps over $V_{>1}$. Define $L_{\le 1} = L_1$ with first factor space $V_1$, and for $k \ge 2$ define $L_{\le k}(x) = x^{L_1} + L'_{x^{L_1},\,<k}(x^{V_{>1}})$, with the $k$-th factor space and linear map of $L$ with prefix $u$ given by those of $L_{>1,\,v}$ at index $k-1$ with prefix $w$, where $v = u^{V_1}$ and $w = u^{V_{>1}}$. Conditions 1--4 are then verified directly from the inductive hypothesis: the direct-sum decomposition of $V_{>1}$ extends to $V$ by adjoining $V_1$, and the sum formula for $L_{\le k}$ follows by unfolding the inductive marginals.
449	\end{proof}
450	
451	The marginal functions, factor spaces, and linear maps of a given CL function $L$ need not be unique. For example, the identity function on $V = \F^n$ is a $1$-level CL function, but it can also be viewed as a $k$-level CL function for any $k \in \{2, \dots, n\}$ with an arbitrary partition of $V$ into factor spaces.
452	
453	\begin{lemma}[Concatenation of conditionally linear functions]\label{lem:cl-concat}
454		\uses{def:cl-func}
455		Let $\ell, k \ge 0$ be integers and let $U = \F^n$, $V = \F^m$ be linear spaces. Suppose $L$ is a $k$-level CL function on $U$ and, for each $u \in L(U)$, $R_u$ is an $\ell$-level CL function on $V$. Then the \emph{concatenation} $T$ of $L$ and $\{R_u\}_u$, defined by
456		\[
457			T(x) = L(x^U) + R_{L(x^U)}(x^V)\,,
458		\]
459		is a $(k+\ell)$-level conditionally linear function on $U \oplus V$.
460	\end{lemma}
461	\begin{proof}
462		By induction on $k$. The case $k = 0$ follows directly from Definition~\ref{def:cl-func}, since then $L = 0$ and $T$ acts by the single $\ell$-level function $R_0$ on the register subspace $V$. For the inductive step, write $L(x^U) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{U_{>1}})$ with complementary register subspaces $U_1$ and $U_{>1}$ of $U$. For each value $x^{L_1}$, the function $T_{>1,\,x^{L_1}}$ on $U_{>1} \oplus V$ sending $x^{U_{>1} \oplus V}$ to $L_{>1,\,x^{L_1}}(x^{U_{>1}}) + R_{x^{L_1} + x^{L_{>1}}}(x^V)$ is the concatenation of the $(k-1)$-level function $L_{>1,\,x^{L_1}}$ with a family drawn from $\{R_u\}$, hence is $(k+\ell-1)$-level by the induction hypothesis. The claim then follows from Definition~\ref{def:cl-func} applied with first subspace $U_1$ and first linear map $L_1$.
463	\end{proof}
464	
465	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
466		\uses{def:cl-func, def:register-subspace}
467		Let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
468		\[
469			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
470		\]
471		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$.
472	\end{lemma}
473	\begin{proof}
474		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 1$ the functions $L^{(j)}$ are linear and the direct sum of linear maps is linear. For the inductive step, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
475	\end{proof}
476	
477	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
478		\uses{def:cl-dist, lem:cl-func-prod}
479		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
480	\end{lemma}
481	\begin{proof}
482		A uniformly random $x \in V$ has independent components $x^{(i)}$, each uniformly distributed in $V^{(i)}$. Hence the pair $(L(x), R(x)) = \bigl( (L^{(i)}(x^{(i)}))_{i=1}^m,\, (R^{(i)}(x^{(i)}))_{i=1}^m \bigr)$ is distributed exactly as the product of the distributions $\mu_{L^{(i)},\,R^{(i)}}$ for $i = 1, 2, \dots, m$.
483	\end{proof}
484	
485	\section{Typed conditionally linear distributions}
486	% Paper section label sec:types kept for cross-reference fidelity. Only the mathematical
487	% typed material (typed CL functions and distributions, graph distributions) is stated
488	% here; the typed sampler and verifier machinery of the source is outside the scope of
489	% the mathematical development.
490	\label{sec:types}
491	
492	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
493	
494	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
495		\uses{def:cl-func}
496		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
497	\end{definition}
498	
499	\begin{definition}[Graph distribution]\label{def:graph-distribution}
500		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
501		\[
502			\mu_G(u, v) =
503			\begin{cases}
504				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
505				0 & \text{otherwise}\,.
506			\end{cases}
507		\]
508		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
509	\end{definition}
510	
511	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
512		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
513		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
514	\end{definition}

  1	\chapter{Extracting the Pauli observables}
  2	\label{chap:qpbt-extraction}
  3	% Paper subsection label sec:separating kept for cross-reference fidelity.
  4	\label{sec:separating}
  5	% Source: references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex,
  6	% lines 1415--1877 (subsection ``Pulling the X and Z measurements apart''
  7	% and the closing proof of the soundness theorem).
  8	
  9	This chapter completes the analysis of the Pauli basis test~\cite{Ji2020MIPStar}. Throughout, $(q,m,d)$ is an admissible parameter tuple (Definition~\ref{def:admissible}), $q = 2^t$, and $M = 2^m$ denotes the number of $q$-ary qudits tested for per player. (The letter $M$ also denotes measurement operators, always carrying super- and subscripts; the meaning is determined by context, as in the source.) We fix a projective strategy for the Pauli basis test game $\mathfrak{G}^{\mathrm{Pauli}}_{(q,m,d)}$ that succeeds with probability at least $1-\eps$, in the setting of Chapter~\ref{chap:qpbt-observables}: the shared state $\ket{\psi}$ on registers $\mathrm{A}$, $\mathrm{B}$ is assumed padded with sufficiently many ancilla qubits in the state $\ket{0}$ (Definition~\ref{def:projective-strategy-setup}), and $\ket{\hat\psi}$ denotes the expanded state on the six registers $\mathrm{A}\mathrm{A}'\mathrm{A}''\mathrm{B}\mathrm{B}'\mathrm{B}''$, obtained by adjoining to each player the two halves of $M$ pairs $\ket{\mathrm{EPR}_q}$ (Definition~\ref{def:expanded-state}). Unless stated otherwise, every $\approx_\delta$ and $\simeq_\delta$ statement below is taken with respect to the state $\ket{\hat\psi}$, over the question distribution named in the statement, with register placements indicated by subscripts; ``all symmetric equivalents'' refers to the register interchanges of Remark~\ref{def:symmetric-equivalents}.
 10	
 11	We use the following objects from the preceding chapters: the combined point projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ acting on the expanded space (Definition~\ref{def:expanded-point-measurement}); the projective polynomial-pair measurement $\{\hat{S}_{g_X,g_Z}\}$ of Lemma~\ref{lem:qld-4-7}, with outcomes pairs of polynomials in $\mathrm{ideg}_{d,m}(\F_q)$ and error function
 12	\[
 13		\delta_S(\eps,m,d,q) = a(md)^a\bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
 14	\]
 15	for universal constants $a > 1$, $0 < b < 1$; the decoding map $\mathrm{Dec}\colon \mathrm{ideg}_{d,m}(\F_q) \to \F_q^{M}$ of the low-degree code (Definition~\ref{def:decoding-map}), which maps a polynomial $g$ to the string of its evaluations on the hypercube $\{0,1\}^m$; and the low-degree encoding $h \mapsto g_h$ together with the vectors $\mathrm{ind}_m(u) \in \F_q^M$, characterized by $h \cdot \mathrm{ind}_m(u) = g_h(u)$ for all $u \in \F_q^m$ \eqref{eq:low-degree-encoding-definition}. The map $h \mapsto g_h$ is linear, and $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u) = g(u)$ for every $g \in \mathrm{ideg}_{d,m}(\F_q)$.
 16	
 17	\section{The pulled-apart measurements and observables}
 18	
 19	The measurement $\{\hat{S}_{g_X,g_Z}\}$ reads out an $X$-polynomial and a $Z$-polynomial simultaneously. We now separate the two readings again, this time as commuting actions on distinct registers: the polynomial outcome is measured on the players' original registers, while a genuine Pauli measurement acts on the EPR register $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
 20	
 21	\begin{definition}[Single-basis marginals of the polynomial-pair measurement]\label{def:s-w-marginals}
 22		\uses{lem:qld-4-7}
 23		Let $\{\hat{S}_{g_X,g_Z}\}$ be the projective measurement of Lemma~\ref{lem:qld-4-7}. For every $g \in \mathrm{ideg}_{d,m}(\F_q)$ define
 24		\[
 25			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 26			\qquad \text{and} \qquad
 27			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 28		\]
 29		the sums ranging over $\mathrm{ideg}_{d,m}(\F_q)$. Since $\{\hat{S}_{g_X,g_Z}\}$ is projective, its elements are mutually orthogonal projectors; hence each $\hat{S}^W_g$, for $W \in \{X,Z\}$, is a projector, and $\{\hat{S}^W_g\}_{g}$ is a projective measurement with outcomes in $\mathrm{ideg}_{d,m}(\F_q)$.
 30	\end{definition}
 31	
 32	\begin{definition}[Pauli dot-product projectors]\label{def:tau-dot-product-projector}
 33		\uses{def:generalized-pauli}
 34		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the projector
 35		\begin{equation}\label{eq:def-tauwu}
 36			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
 37		\end{equation}
 38		For each fixed $\tilde{u}$, the family $\{\tau^W_a(\tilde{u})\}_{a \in \F_q}$ is a projective measurement on $(\C^q)^{\ot M}$.
 39	\end{definition}
 40	
 41	\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
 42		\uses{def:s-w-marginals, def:tau-dot-product-projector, def:decoding-map}
 43		For all $W \in \{X,Z\}$ and $\tilde{u} \in \F_q^{M}$ define the measurement $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ by
 44		\begin{equation}\label{eq:tilde_M}
 45			\tilde{M}^{W,\tilde{u}}_a = \sum_{g} \hat{S}^W_g \ot \tau_{(\mathrm{Dec}(g) \cdot \tilde{u}) - a}^W(\tilde{u})\;,
 46		\end{equation}
 47		the sum ranging over $g \in \mathrm{ideg}_{d,m}(\F_q)$. If $\hat{S}^W_g$ is viewed as an operator acting on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), then $\tilde{M}^{W,\tilde{u}}_a$ acts on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ (resp.\ $\mathrm{B}\mathrm{B}'\mathrm{B}''$), the $\tau^W$ factor acting on $\mathrm{A}''$ (resp.\ $\mathrm{B}''$). Each family $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ is a projective measurement, because the $\hat{S}^W_g$ and the $\tau^W$ projectors are projective and, for each $g$, the projectors $\tau^W_{(\mathrm{Dec}(g)\cdot\tilde{u})-a}(\tilde{u})$ sum to the identity as $a$ ranges over $\F_q$.
 48	\end{definition}
 49	
 50	\begin{definition}[Pulled-apart Pauli observables]\label{def:tilde-w-observables}
 51		\uses{def:tilde-m-measurement, def:dual-self-dual-normal-basis, def:subfield-trace, def:generalized-pauli, lem:qld-4-7}
 52		Let $\{e_j\}_{j \in \{1,\ldots,t\}}$ be the self-dual basis for $\F_q$ over $\F_2$ of Definition~\ref{def:dual-self-dual-normal-basis}, and let $\tr = \tr_{q \to 2} \colon \F_q \to \F_2$ be the subfield trace. For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^M$, and $j \in \{1,\ldots,t\}$ define the observable
 53		\begin{equation}\label{eq:def-tildewj}
 54			\tilde{W}^j(\tilde{u}) = \sum_{a \in \F_q} (-1)^{\tr(e_j a)} \, \tilde{M}_a^{W,\tilde{u}}\;,
 55		\end{equation}
 56		acting on the same registers as $\tilde{M}^{W,\tilde{u}}_a$. Let $\tau^W(\cdot)$ denote the generalized Pauli $W$ observable (Definition~\ref{def:generalized-pauli}). Expanding $\tau^W(e_j \tilde{u})$ over the projectors $\tau^W_h$, grouping the $h$ according to the value $a = h \cdot \tilde{u}$, and changing variables yields the exact identity
 57		\begin{equation}\label{eq:tildewj-product-form}
 58			\tilde{W}^j(\tilde{u})
 59			= \Big( \sum_{g_X,g_Z} (-1)^{\tr(e_j (\mathrm{Dec}(g_W) \cdot \tilde{u}))} \, \hat{S}_{g_X,g_Z} \Big) \ot \tau^W(e_j \tilde{u})\;,
 60		\end{equation}
 61		where $g_W$ denotes $g_X$ if $W = X$ and $g_Z$ if $W = Z$. In particular $\tilde{W}^j(\tilde{u})$ is Hermitian and squares to the identity, because the measurement $\{\hat{S}_{g_X,g_Z}\}$ is projective. Moreover, a direct calculation from \eqref{eq:tildewj-product-form} shows that these observables satisfy exactly the relations of the generalized Pauli group: for all $j,j' \in \{1,\ldots,t\}$ and $\tilde{u},\tilde{v} \in \F_q^M$,
 62		\[
 63			\tilde{X}^j(\tilde{u})\, \tilde{Z}^{j'}(\tilde{v}) =
 64			\begin{cases}
 65				\tilde{Z}^{j'}(\tilde{v})\, \tilde{X}^j(\tilde{u}) & j \neq j'\;, \\
 66				(-1)^{\tr((e_j \tilde{u}) \cdot (e_j \tilde{v}))}\, \tilde{Z}^{j}(\tilde{v})\, \tilde{X}^j(\tilde{u}) & j = j'\;.
 67			\end{cases}
 68		\]
 69	\end{definition}
 70	
 71	\section{Consistency with the points measurements}
 72	
 73	The next lemma shows that the pulled-apart measurements are consistent with the original points measurements of the strategy, and self-consistent. In its statement, and for the remainder of the chapter, $\delta_S$ denotes the function of Lemma~\ref{lem:qld-4-7}, enlarged by an adjustment of the universal constants $a$ and $b$ so as to also dominate additional error terms of order $\sqrt{\eps}$, $\eps$, and $md/q$ that the source absorbs into $\delta_S$ along the way; such an adjustment is possible since, after shrinking $b$ to at most $1/2$, the term $\eps^b$ dominates $\sqrt{\eps}$ and $\eps$ for $\eps \leq 1$, while $(md)^a q^{-b}$ dominates $md/q$.
 74	
 75	\begin{lemma}[Consistency and self-consistency of the pulled-apart measurements]\label{lem:qld-construct-the-paulis}
 76		\uses{def:tilde-m-measurement, def:tilde-w-observables, def:projective-strategy-setup, def:expanded-state, def:consistency, def:povm-distance, lem:qld-4-7, def:indicator-vector}
 77		The measurements $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ and observables $\tilde{W}^j(\tilde{u})$ satisfy the following properties.
 78		% The paper's statement also quantifies item 1 over j, but j does not occur
 79		% in item 1; the vacuous quantifier is dropped here.
 80		\begin{enumerate}
 81			\item (\textbf{Consistency with points measurements}) For all $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
 82			\[
 83				\Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \simeq_{\delta_S} M^{(\mathrm{Point},W),u}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''}
 84			\]
 85			and
 86			\[
 87				\tilde{M}^{W,\mathrm{ind}_m(u)}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \simeq_{\delta_S} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot M^{(\mathrm{Point},W),u}_a\;,
 88			\]
 89			with the answer summation over $a \in \F_q$.
 90			\item (\textbf{Self-consistency}) For all $W \in \{X,Z\}$ and $j \in \{1,\ldots,t\}$, on average over uniformly random $\tilde{u} \in \F_q^{M}$,
 91			\[
 92				\tilde{W}^j(\tilde{u}) \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \approx_{\delta_S} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{W}^j(\tilde{u})\;.
 93			\]
 94		\end{enumerate}
 95	\end{lemma}
 96	\begin{proof}
 97		\uses{lem:qld-4-7, lem:qld-constructing-the-paulis-helper, def:expanded-point-measurement, lem:qld-win-implications, lem:qld-comm-cons, fact:add-a-proj, fact:agreement, fact:data-processing, def:bracket, lem:povm-to-obs, lem:schwartz-zippel-total-degree}
 98		For the first item, in the case where $M^{(\mathrm{Point},W),u}_a$ acts on register $\mathrm{A}$ and $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ on $\mathrm{B}\mathrm{B}'\mathrm{B}''$, expanding \eqref{eq:tilde_M}, using the definition of the combined projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) and the identity $\mathrm{Dec}(g)\cdot\mathrm{ind}_m(u) = g(u)$, gives
 99		\[
100			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} M^{(\mathrm{Point},W),u}_a \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \ket{\hat\psi}
101			= \E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}
102			\geq 1 - \delta_S
103		\]
104		by Lemma~\ref{lem:qld-4-7}, and the register-interchanged relation follows analogously. For the second item one first shows that, on average over uniformly random $\tilde{u} \in \F_q^M$,
105		\begin{equation}\label{eq:qld-pulling-cons}
106			\bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_S} \bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}\;:
107		\end{equation}
108		right-multiplying by the resolution $\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_S} \Id$ of Lemma~\ref{lem:qld-constructing-the-paulis-helper} (with Lemma~\ref{fact:add-a-proj}) and expanding the products of $\tau^W$ projectors via \eqref{eq:def-tauwu} and $h \cdot \mathrm{ind}_m(u) = g_h(u)$ places $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{A}\mathrm{A}'\mathrm{A}''}$ within $O(\delta_S)$ of a sum over pairs $(g,h)$ with $(\mathrm{Dec}(g)-h)\cdot\tilde{u} = a$. One then applies, in turn, the self-consistency of the points measurements (Lemma~\ref{lem:qld-win-implications}) at cost $\eps$; the exact identity $\ket{\hat\psi} = \sum_{h'} (\tau^W_{h'})_{\mathrm{B}'} \ot (\tau^W_{h'})_{\mathrm{B}''} \ket{\hat\psi}$ of the EPR registers; Lemma~\ref{lem:qld-constructing-the-paulis-helper} twice more (once through a Cauchy--Schwarz detour of cost $O(\sqrt{\eps})$ using the self-consistency of the $\hat{M}^{(\mathrm{Point},W),u}_a$, Lemma~\ref{lem:qld-comm-cons}); and finally a Schwartz--Zippel step (Lemma~\ref{lem:schwartz-zippel-total-degree}, for polynomials of total degree at most $md$) which replaces the event $(g'-g_{h'})(u) = (g-g_h)(u)$ by the polynomial identity $g'-g_{h'} = g-g_h$ at cost $md/q$. The resulting expression
109		\[
110			\sum_{\substack{g,h,g',h': \\ g' - g_{h'} = g - g_h \\ (\mathrm{Dec}(g)-h)\cdot \tilde{u} = a}}
111			\Bigl((\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\tau_h^W)_{\mathrm{A}''} \Bigr) \cdot \Bigl( (\hat{S}^W_{g'})_{\mathrm{B}\mathrm{B}'} \ot (\tau_{h'}^W)_{\mathrm{B}''} \Bigr)
112		\]
113		is symmetric under exchanging $(g,h)$ with $(g',h')$, so the same derivation bounds its distance to $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}$, and \eqref{eq:qld-pulling-cons} follows after absorbing the error terms $O(\sqrt{\eps})$ and $O(md/q)$ into $\delta_S$. Finally, since $\{\tilde{M}^{W,\tilde{u}}_a\}$ is projective, Item~2 of Lemma~\ref{fact:agreement}, data processing along the map $a \mapsto \tr(e_j a)$ (Lemma~\ref{fact:data-processing}), and Item~1 of Lemma~\ref{fact:agreement} yield $(\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_S} (\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\mathrm{B}\mathrm{B}'\mathrm{B}''}$ with answer summation over $b \in \F_2$, and Lemma~\ref{lem:povm-to-obs} converts this into the claimed self-consistency of the observables $\tilde{W}^j(\tilde{u})$.
114	\end{proof}
115	
116	The following lemma was used in several derivations above. It is stated after Lemma~\ref{lem:qld-construct-the-paulis} to follow the source, but its proof depends only on Lemma~\ref{lem:qld-4-7} and Lemma~\ref{lem:qld-comm-cons}, so there is no circularity.
117	
118	\begin{lemma}[The marginals absorb the point measurements]\label{lem:qld-constructing-the-paulis-helper}
119		\uses{def:s-w-marginals, def:expanded-point-measurement, def:expanded-state, def:povm-distance, lem:qld-4-7, def:symmetric-equivalents}
120		For $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
121		\begin{equation}\label{eq:qld-sg-cons}
122			\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_S} \Id
123		\end{equation}
124		and
125		\begin{equation}\label{eq:qld-sg-cons2}
126			\bigl(\hat{S}^W_g \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)})\bigr)_{\mathrm{A}\mathrm{A}'} \approx_{\delta_S} 0\;,
127		\end{equation}
128		where the answer summation is over $g \in \mathrm{ideg}_{d,m}(\F_q)$, and where in \eqref{eq:qld-sg-cons2} an additional error term of order $\eps$ is absorbed into $\delta_S$. Furthermore, all symmetric equivalents of these approximations also hold (Remark~\ref{def:symmetric-equivalents}).
129	\end{lemma}
130	\begin{proof}
131		\uses{lem:qld-4-7, fact:agreement, fact:add-a-proj, def:bracket, lem:qld-comm-cons}
132		The point-consistency conclusion of Lemma~\ref{lem:qld-4-7} states that, on average over $u \in \F_q^m$,
133		\[
134			\bra{\hat\psi} \sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point}, W), u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \ket{\hat\psi} \geq 1 - \delta_S\;,
135		\]
136		which says exactly that the operator on the left-hand side of \eqref{eq:qld-sg-cons} is $\delta_S$-consistent with $\Id$; Lemma~\ref{fact:agreement} upgrades this $\simeq_{\delta_S}$ statement to the $\approx_{\delta_S}$ statement \eqref{eq:qld-sg-cons}. For \eqref{eq:qld-sg-cons2}, the same consistency, written with the coarse-graining $\hat{S}^W_{[g(u)=a]} = \sum_{g : g(u) = a} \hat{S}^W_g$ as $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{\delta_S} (\hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{B}\mathrm{A}''}$ with answer summation over $a \in \F_q$, is left-multiplied by $(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'}$ using Lemma~\ref{fact:add-a-proj}; moving $\hat{M}^{(\mathrm{Point}, W), u}_a$ from registers $\mathrm{B}\mathrm{A}''$ to $\mathrm{A}\mathrm{A}'$ costs a further $\eps$ by Cauchy--Schwarz together with the self-consistency of the $\hat{M}^{(\mathrm{Point}, W), u}_a$ (Lemma~\ref{lem:qld-comm-cons}), giving
137		\[
138			(\hat{S}^W_{[g(u)=a]})_{\mathrm{A}\mathrm{A}'} \approx_{O(\delta_S + \eps)} (\hat{S}^W_{[g(u)=a]} \cdot \hat{M}^{(\mathrm{Point}, W), u}_{a})_{\mathrm{A}\mathrm{A}'}\;.
139		\]
140		Expanding
141		\[
142			\E_u \sum_g \bigl\| (\hat{S}^W_{g} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{g(u)}))_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi} \bigr\|^2
143			= \E_u \sum_a \bra{\hat\psi} \bigl((\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a}) \cdot \hat{S}^W_{[g(u)=a]} \cdot (\Id - \hat{M}^{(\mathrm{Point}, W), u}_{a})\bigr)_{\mathrm{A}\mathrm{A}'} \ket{\hat\psi}
144		\]
145		and bounding the right-hand side by $O(\delta_S + \eps)$ using the two approximations above yields \eqref{eq:qld-sg-cons2} after absorbing $\eps$ into $\delta_S$. The symmetric equivalents follow by the same argument with the register bipartitions interchanged.
146	\end{proof}
